        "لك المجد أيها المحسن إلى النفوس والأجساد، لك المجد أيها المشرق شمسه على الأشرار والأخيار، والمرسل مطره على الصدّيقين والظالمين. لك المجد أيها الفادي كافة الأمم، وكل الطبيعة البشرية. أنت يا رب هو الصالح وحدك، أنت هو النور الذي يفوق كل نور، والسرور الذي يفوق كل سرور، والراحة التي تسمو فوق كل راحة! أنت هو الحياة الأبدية، والخلاص الدائم إلى الأبد.",
