        "غذّني معهم من عشب أسرارك الإلهية، هؤلاء الذين طبيعتهم هي القلب النقي، ومن خلالهم تشرق وتعلن رؤيتك التي تملأ بالتعزية والبهجة كل من يعمل بجد، ويتحمّل الصعوبات. أيها السيد الرب يسوع المسيح، الذي بكى على صديقه لعازر، وذرف دموع الأسى الحنو عليه، اقبل دموع مرارتي، واشفِ آلامي من خلال ما تحمّلته عني من آلام!",
