        "اجعلنا مستحقّين لهذه الاستنارة بنعمتك ومحبتك لبني البشر، يا مخلصنا يسوع المسيح، الآن وإلى دهر الدهور، آمين. جسدك الذي رُفع على خشبة الصليب، فليحفّز عقلي، الذي انحدر إلى أسفل بواسطة الشياطين، لكي يرتفع نحوك طائرًا. رأسك التي انحنت إلى أسفل على الصليب فلترفع رأسي التي ضربت بقسوة من المقاومين.",
        "يداك كليّتا القداسة، اللتان سُمّرَتا على الصليب، فلترفعاني من هوة دماري، وتقرّباني إليك، كما وعد بذلك فمك الكلّي القداسة. وجهك الذي استقبل اللطم والبصاق بواسطة الأثمة، فليشرق على وجهي المظلم بالخطايا. روحك التي قدّمتها للآب وأنت على الصليب، تقودني إليك حسب نعمتك.",
        "ليس عندي يا سيدي أنين القلب ولا توبة أو ندامة، ليس لديّ دموع التوسّل! كما أن الشرّ هو حرمان من الخير، فإن الظلمة هي حرمان من النور. ربي أشكرك... لقد ملأت قلبي من أنوارك... ألست أنت ملك الملوك ورب الأرباب؟ الذي وحده له عدم الموت، ساكنًا في نور لا يُدنى منه. عندما عرفت نفسي عرفتك أيضًا، لأن معرفتي لك نور لسبيلي.",
