      text: [
        "أيها النور غير المنظور! أيها البهاء الذي لا يراه بهاء آخر! أنت هو النور لأولاد النور! أنت هو النور والبهاء، أمامك تصير كل الأنوار ظلمات، وكل ضياء بالنسبة لك ليس إلا ظلامًا! أنت هو النور الذي تختفي أمامك كل الأنوار المخلوقة!",
        'أنت هو "النور" مصدر كل الأنوار، و"البهاء" ينبوع كل بهاء! أنت هو النور والبهاء، أمامك تصير كل الأنوار ظلمات، وكل ضياء بالنسبة لك ليس إلا ظلامًا! أنت هو البهاء الذي بك تصير الظلمة نورًا، وبك يتلألأ الظلام لمعانًا! أنت هو النور الأسمى، لا تحجبك سحابة ما، ولا يعوقك بخار، يعجز الليل عن أن يسدل بظلامه عليك، لا يعوقك حاجز ولا تُغرقك ظلال!',
        "ربّي وإلهي... يا نور نفسي... لا تتوقّف قط عن إنارة خطواتي حتى إذا ما اكتشفت هوة جلالك، بقوة بهاء لاهوتك ذاته، وعمل البهاء المنعكس علي منك! لا تتركني قط، لئلا يتزايد جهلي وتكثر شروري، فبدونك أصير فارغًا وبائسًا! بدونك لا يكون لأحد صلاح، إذ أنت هو الحق والصلاح الحقيقي وحده!",
        "إنني أتكلّم عن ذلك السارق الذي أراد أولاً أن يغتصب مجدك، وإذ هو مملوء بالغرور ألقى بنفسه في الهاوية التي حفرها لنفسه! هذا ما أعترف به؛ وهذا هو ما أعرفه، يا الله إلهي، أنه حيثما وُجدت بدونك لا يكون لي غير الشقاء — في الداخل كما في الخارج — لأن كل غنى غير إلهي إنما هو بالنسبة لي فقر مدقع! والآن ربي وحياتي، إنه منذ سقوطه العظيم لا ينشغل إلا كيف يطارد أولادك!",
        "أيها الملك العظيم، اطرده من أمام أعيننا نحن خرافك، وأضئ لنا جيدًا بنورك حتى نتجنب فخاخه الخادعة ونأتي إليك مبتهجين! فإنني أعلم إنني ما كنت مستحقًا أن أُدعى أسقفًا، لأنني انشغلت بهذا العالم، لكن نعمتك جعلتني على ما أنا عليه. وفي الحقيقة إنني أصغر جميع الأساقفة، وأقلهم استحقاقًا.",
        "ومع ذلك فقد تعهدت ببعض الأعمال الخاصة بكنيستك المقدسة، وسهرت على هذه الثمرة، وإذ اخترتني للكهنوت وأنا مفقود، لا تسمح بعد أن أكون مفقودًا وأنا كاهن... يا رب، هب لي أن تكون سقطات كل إنسان أمامي، حتى أحتملها معه، ولا أنتهره في كبرياء، بل أحزن وأبكي.",
      ],
