      title: "احفظ يا رب عملك",
      author: "القديس أمبروسيوس",
      source: "من كتاب «صلوات القديسين» — القمص تادرس يعقوب ملطي (Concerning Repentance, Book 2)",
      text: [
        'ففي بكائي من أجل الآخرين أبكي على نفسي قائلاً: "هي (ثامار) أبرّ مني" (تك ٣٨: ٢٦). لتهب لي يا رب أن تأتي إلى قبري، فتسكب الدموع عليّ، حيث جفت عيناي ولم تعودا قادرتين على سكب دموع كهذه من أجل معاصي.',
        'إن بكيت يا رب علي (كما على لعازر) فسأُنقذ... أنت تدعوني من قبر جسدي هذا، قائلاً: "هلمّ خارجًا"، حتى لا يعود تفكيري ينحصر في حدود جسدي هذا الضيق، بل يخرج نحوك، ويحيا في النور، فلا أعود أفكر في أعمال الظلمة بل في أعمال النور...',
        "نادِ يا رب خادمك، رغم ربطه بسلسلة الخطايا، وتقييد قدميه ويديه، فإنه الآن مدفون في قبر الأفكار والأعمال الميتة. لكن عندما تدعوني فسأقوم حرًا، وأصير أحد الجالسين في وليمتك وتفوح في بيتك رائحة طيب ذكية.",
        'إن كنت قد وهبت لأحد أن يخلص، فإنك تحافظ عليه أيضًا، فيقال عني: "أنظر! إنه لم يحضر من وسط الكنيسة، ولا تأدب منذ طفولته، بل كان هاربًا من الحكم، فُجذب من بين أباطيل العالم، ودخل في صفوف المرتلين، بدلاً من أن يكون بين المولولين، وقد ثابر في كهنوته لا بقوته الخاصة، بل بنعمة المسيح، وصار جالسًا بين المدعوين في الوليمة السمائية".',
        "احفظ أيها الرب عملك، واحرس عطاياك التي وهبتها حتى لذاك الذي هرب منها. بالحقيقة أنت أفضل من اللبن وأحلى من الشهد، وأكثر ضياء من كل نور. الذهب والفضة والأحجار الكريمة لا تقارن بك في داخل قلبي. كل مسرّات العالم لا تظهر لي إلا كرائحة كريهة وبلا طعم... إذ قد تذوّقت عذوبتك مرة، ورأيت جمال بيتك.",
        "أيها النار الإلهي، يا من لهيبك لا ينقطع بل هو دائم الحرارة. أيها الحب الدائم الحرارة، يا من لا تفتر قط. أيها الحب الإلهي احتضني. امتلكني تمامًا... فألتصق بك تمامًا! آه! ليتني قدامي! أحبك يا إلهي لأنك أحببتني أولاً.",
      ],
