      author: "القديس نيقولاي فيليميروفيتش",
      source:
        "نص زوّد به المستخدم — القديس نيقولاي فيليميروفيتش، أسقف صربي (١٨٨١-١٩٥٦م)، أعلنت قداسته الكنيسة الأرثوذكسية الصربية عام ٢٠٠٣م",
      text: [
        "بارك أعدائي يارب، فأنا أباركهم ولا ألعنهم. الأعداء نقلوني إلى شرف معانقتك أكثر مما فعل الأصدقاء. الأصدقاء ربطوني بالأرض، أما الأعداء فأطلقوني من الأرض، وهدموا كل تطلعاتي في العالم. الأعداء جعلوني غريباً عن الممالك الدنيونية، وساكناً غريباً عن العالم. وكما يجد الحيوان المُصطّاد ملجأً أكثر أماناً من الحيوان الطليق، هكذا أنا أيضاً، وجدت ملجأً أكثر آماناً بإضطهادي من قبل الأعداء، وقد أخفيت نفسي تحت خيمتك، حيثما لا يستطيع الأصدقاء أو الأعداء أن يقتلوا نفسي. بارك أعدائي يارب، فأنا أباركهم ولا ألعنهم.",
        "هم قد أعترفوا بذنوبي أمام العالم عوضاً عني. هم قد عاقبوني، حينما ترددت في معاقبة نفسي. هم قد عذبوني، حينما حاولت الهروب من العذاب. هم قد وبخوني، حينما كنت أتملق نفسي. وبصقوا علي، حينما ملأت نفسي بالتكبر والعجرفة. بارك أعدائي يارب، فأنا أباركهم ولا ألعنهم.",
        "حينما ظننت نفسي حكيماً، دعوني أحمق. حينما جعلت من نفسي جباراً، هزأوا بي كما لو أني قزم. حينما أردت قيادة الناس، دفعوني إلى الخلف. حينما أسرعت لإغناء نفسي، منعوني بيد من حديد. حينما ظننت أنني سأنام في سلام، أيقظوني من النوم. حينما حاولت بناء بيتاً من أجل حياة مديدة هانئة، هدموه وطردوني منه. حقاً، قد قطع أعدائي كل إرتباطي بالعالم، فمددت يدي نحو طرف ثوبك. بارك أعدائي يارب، فأنا أباركهم ولا ألعنهم.",
        "باركهم وأكثرهم، أكثرهم وأجعلهم حتى أكثر مرارة ضدّي. حتى ما يكون هروبي إليك هروباً نهائياً بلا عودة. حتى ما يتبعثر كل رجاء في البشر مثل أنسجة العنكبوت، حتى ما يبدأ هذا الصفاء المطلق بإمتلاك روحي، حتى ما يصير قلبي قبراً لتوائمي الشريرين: التكبر والغضب. حتى ما أجمع وأكدس كل كنوزي في السماء، آه، حتى ما أتحرر أخيراً من خداع الذات، الذي يورطني في الشبكة المُخيفة التي للحياة الخادعة.",
        "الأعداء علموني الشيء الذي لا يتعلمه أي أحد بسهولة، وهو أن الشخص في العالم ليس له أعداء سوى نفسه. الشخص يكره أعداءه فقط عندما يُخفق في إدراك أنهم ليسوا أعداء بل أصدقاء قساة. أنه حقاً صعب بالنسبة لي أن أقول من أحسن إليَّ أكثر ومن أضرّني أكثر في هذا العالم: الأصدقاء أم الأعداء. لذلك بارك يارب كلاهما: أصدقائي وأعدائي.",
        "العبد يلعن الأعداء لأنه لا يفهم، أما الابن فيباركهم لأنه يفهم. لأن الابن يعلم يقيناً أن أعداءه لا يستطيعون أن يمسوا حياته. لذلك فهو يخطو بحرية في وسطهم، ويصلي لله من اجلهم.",
      ],
